<?php $editing = isset($item['id']); $base = $type === 'page' ? 'pages' : 'posts'; $pageTitle = ($editing ? 'Edit ' : 'Create ') . ucfirst($type); ?>
<?php if (!empty($error)): ?><div class="flash error"><?= e($error) ?></div><?php endif; ?><form method="post" action="<?= $editing ? '/admin/' . e($base) . '/' . (int) $item['id'] : '/admin/' . e($base) ?>"><?= csrf_field() ?><div class="content-grid"><div><div class="card"><div class="field"><label>Title</label><input name="title" value="<?= e($item['title'] ?? '') ?>" required></div><div class="field"><label>Slug</label><input name="slug" class="code" value="<?= e($item['slug'] ?? '') ?>" placeholder="generated-from-title"></div><div class="field"><label>Excerpt</label><textarea name="excerpt" style="min-height:110px"><?= e($item['excerpt'] ?? '') ?></textarea></div><div class="field"><label>Content (HTML allowed for trusted administrators)</label><textarea name="body" class="code"><?= e($item['body'] ?? '') ?></textarea></div></div></div><aside><div class="card"><div class="field"><label>Status</label><select name="status"><option value="draft"<?= selected($item['status'] ?? 'draft','draft') ?>>Draft</option><option value="published"<?= selected($item['status'] ?? 'draft','published') ?>>Published</option></select></div><button class="btn primary" type="submit"><?= $editing ? 'Save changes' : 'Create' ?></button><a class="btn" href="/admin/<?= e($base) ?>">Cancel</a></div></aside></div></form>
